export type CardGlyphName = keyof typeof CARD_GLYPHS;

/** True for a name this module actually draws — the authored `.mjs` is data,
 *  so a typo must fail visibly at the seed rather than render nothing. */
export function isCardGlyph(name: unknown): name is CardGlyphName {
  return typeof name === "string" && name in CARD_GLYPHS;
}

export function CardGlyph({ name, size = 28, tone }: { name: CardGlyphName; size?: number; tone: string }) {
  const Glyph = CARD_GLYPHS[name];
  return <Glyph size={size} tone={tone} />;
}
